{
  "body": {
    "authority_unchanged": true,
    "engineering_blockers": [
      "Exact physical DUT marking, package, orderable suffix, and package-specific pinout.",
      "Exact programmer identity, voltage levels under load, supported clock rate, and timing behavior.",
      "Selected TXU0304 orderable package, footprint, availability, and assembly constraints.",
      "Complete VIH/VIL/VOH/VOL and propagation-delay timing budget at the selected supplies and load.",
      "Local 1.8 V supply implementation, current budget, sequencing, decoupling, protection, and OE behavior.",
      "Schematic/ERC/PCB/DRC results and all physical measurements."
    ],
    "ok": true,
    "physical_authority_granted": false,
    "pre_fabrication_plan": {
      "actions": [
        {
          "action_id": "identify-dut",
          "depends_on": [],
          "description": "Obtain physical marking/package/orderable identity and match package-specific pinout; resolve auxiliary pin requirements before assigning footprints.",
          "source_refs": [
            {
              "claim_id": "dut-package-dependent-pinout",
              "source_id": "src-dut-datasheet"
            }
          ],
          "status": "pending"
        },
        {
          "action_id": "identify-host",
          "depends_on": [],
          "description": "Resolve exact programmer and obtain voltage-under-load and timing evidence; no clock limit can currently be assigned.",
          "status": "pending"
        },
        {
          "action_id": "select-translator",
          "depends_on": [],
          "description": "Select exact TXU0304 package, footprint, availability and assembly constraints; verify logical mapping against its pin table.",
          "source_refs": [
            {
              "claim_id": "txu-fixed-direction-map",
              "source_id": "src-translator-fixed-datasheet"
            }
          ],
          "status": "pending"
        },
        {
          "action_id": "design-supply",
          "depends_on": [
            "identify-dut",
            "identify-host",
            "select-translator"
          ],
          "description": "Specify local 1.8 V rail with tolerance/transients in DUT operating range, current budget, decoupling, protection, ground return and sequencing. Design OE default low and verify disabled/unpowered behavior and DUT safe biasing.",
          "source_refs": [
            {
              "claim_id": "dut-operating-supply",
              "source_id": "src-dut-datasheet"
            },
            {
              "claim_id": "txu-supply-range",
              "source_id": "src-translator-fixed-datasheet"
            },
            {
              "claim_id": "txu-output-disable",
              "source_id": "src-translator-fixed-datasheet"
            }
